/**
 * Used internally as a shorter version of the ColumnInstance type
 */
export type ColumnMinInstance = {
    id: string;
    accessor?: string;
    Header: string;
    columns?: ColumnMinInstance[];
    parent?: {
        id: string;
        columns?: ColumnMinInstance[];
        Header: string;
    };
    fontStyle?: 'text' | 'code';
    lineWrap?: boolean;
};
